import{_ as m,l as o,o as e,c as l,v as i,p as r,x as n,d as s,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"汉明码","description":"","frontmatter":{"title":"汉明码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hamming-code.md","filePath":"cs/hamming-code.md","lastUpdated":1789023840000}'),c={name:"cs/hamming-code.md"};function h(_,a,E,H,f,g){const t=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="汉明码" tabindex="-1">汉明码 <a class="header-anchor" href="#汉明码" aria-label="Permalink to &quot;汉明码&quot;">​</a></h1><div class="epigraph"><p>校验矩阵的列是全部非零向量时，伴随式直接给出 1 位翻转的位置；$(2^m-1,2^m-1-m)$ 码完美，$d_{\\min}=3$。</p><footer>—— 据 Hamming, 1950；MacWilliams and Sloane 整理</footer></div><p>上一课<a href="/cs/channel-capacity">信道容量</a> 是存在性。<a href="/cs/hamming-distance">汉明距离</a> 与纠错直觉课已经用 \\((7,4)\\) 当例子。缺口是把 <strong>Hamming 码</strong>写成线性码：生成、校验、伴随式译码，不再停在「相异位数」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性码：\\(C=\\ker H\\)。Hamming： \\(H\\) 的列是 \\(\\mathbb{F}_2^m\\setminus\\{0\\}\\) 各一次。长 \\(n=2^m-1\\)，冗余 \\(m\\)，维 \\(k=n-m\\)。任一重量 1 的错误向量 \\(e\\)，\\(He\\) 等于 \\(H\\) 的某列，即错误位置。\\(d_{\\min}=3\\)（无重量 1、2 的码字），纠 1 位。球半径 1 填满空间：完美码。</p><p>\\((7,4)\\) 是 \\(m=3\\)。主干奇偶/CRC 是 \\(d=2\\) 检错；这里 \\(d=3\\) 纠错。</p><h3 id="伴随式不是哈希" tabindex="-1">伴随式不是哈希 <a class="header-anchor" href="#伴随式不是哈希" aria-label="Permalink to &quot;伴随式不是哈希&quot;">​</a></h3><p>\\(He\\) 是线性图像，为定位服务。密码学哈希不可逆；这里 \\(H\\) 公开且故意可解 1 位错。</p><p><span class="marginnote">Hamming 1950。完美码稀少：Hamming、Golay 等。MacWilliams–Sloane 是编码圣经。本课不证 Hamming 界等式的全部组合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(m=3\\) 的 \\(H\\)。编码：信息位乘 \\(G\\)（\\(H\\) 的正交补）。译码：算伴随式，翻对应位，或为零则无错。两位错会误纠——容量课的 \\(f\\) 大时 Hamming 不够，要后课更强码。</p>',11)),(e(),r(p,null,{default:n(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HMAT%5B%22H%20%E5%88%97%3D%E5%85%A8%E4%BD%93%E9%9D%9E%E9%9B%B6%22%5D%20--%3E%20SYN%5B%22%E4%BC%B4%E9%9A%8F%E5%BC%8F%20He%22%5D%0A%20%20SYN%20--%3E%20POS%5B%221%20%E4%BD%8D%E9%94%99%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20POS%20--%3E%20COR%5B%22%E7%BF%BB%E5%9B%9E%E7%A0%81%E5%AD%97%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性使译码成矩阵乘，硬件友好。速率 \\((n-m)/n\\to 1\\)，但只纠 1 位，\\(n\\) 大时对 BSC 的 \\(f\\) 固定会失败——达不到容量。本课是构造的第一颗钉，不是容量达成者。</p><p>扩展 Hamming 加总偶校验，\\(d=4\\)，可纠 1 检 2。</p><p>对偶：Hamming 的对偶是单纯码，本课不展开。扩展 Hamming \\((8,4)\\) 在计算机内存 ECC 常见。两位错的伴随式非零且不等于任何列，若再加总校验可检出「双错」而不误纠。\\(n\\) 增大只纠 1 位时，BSC 上块错误率上升，故它不是容量码。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入循环码的多项式观点（CRC 主干已有检错多项式）。Reed–Solomon 是更大字母表，下一课。后课默认：二元完美 1 纠错码即 Hamming 族。下一课 RS。</p><p>伴随式定位依赖列集合是全部非零向量：这是完美 1 纠错的组合来源。两位错会映射到错误的列，故 \\(f\\) 不小时要换码。线性译码是矩阵乘，不是哈希。</p><p>上一课留下的缺口在本课收口；「汉明码」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hamming：\\(H\\) 列穷尽非零，伴随式定位 1 位错。</li><li>\\(d_{\\min}=3\\)，完美；速率高但不抗许多错。</li><li>线性码译码 = 乘 \\(H\\)。</li><li>出处：Hamming, 1950；MacWilliams and Sloane。</li></ul>',10))])}const S=m(c,[["render",h]]);export{B as __pageData,S as default};
